func resolveConfigPath(configPath string) (string, bool, error) {
	if strings.TrimSpace(configPath) != "" {
		return configPath, true, nil
	}
	if path := os.Getenv("PROXMOX_CONFIG"); path != "" {
		return path, true, nil
	}
	dir, err := cliutil.ConfigDir()
	if err != nil {
		return "", false, err
	}
	return filepath.Join(dir, "config.toml"), false, nil
}

func LegacyConfigPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve legacy config path: %w", err)
	}
	return filepath.Join(home, ".config", "proxmox-cli", "config.toml"), nil
}

func readConfigFile(path string, cfg *Config, owner string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return parseConfigData(data, cfg, path, owner)
}

func parseConfigData(data []byte, cfg *Config, path string, owner string) error {
	if err := toml.Unmarshal(data, cfg); err != nil {
		return fmt.Errorf("parsing %s %s: %w", owner, path, err)
	}
	cfg.configOwner = owner
	return nil
}
func FileHasCredentialFields(path string) (bool, error) {
	var cfg Config
	if err := readConfigFile(path, &cfg, "credential probe"); err != nil {
		return false, err
	}
	return cfg.hasCredentialFields(), nil
}

func (c *Config) addCredentialRefusal(refusal cliutil.CredentialRefusal) {
	if c == nil || !refusal.CredentialsPresent {
		return
	}
	c.CredentialRefusals = append(c.CredentialRefusals, refusal)
	cliutil.ReportCredentialRefusal(refusal)
}

func (c *Config) HasCredentialRefusals() bool {
	return c != nil && len(c.CredentialRefusals) > 0
}

func (c *Config) CredentialRefusalSummaries() []string {
	if c == nil || len(c.CredentialRefusals) == 0 {
		return nil
	}
	out := make([]string, 0, len(c.CredentialRefusals))
	for _, refusal := range c.CredentialRefusals {
		out = append(out, refusal.Error())
	}
	return out
}

func (c *Config) CredentialRefusalError() error {
	summaries := c.CredentialRefusalSummaries()
	if len(summaries) == 0 {
		return nil
	}
	return fmt.Errorf("stored credentials refused: %s", strings.Join(summaries, "; "))
}

// normalizeEndpointTemplateValue cleans up a server-URL template value the
// user has likely pasted from a browser address bar; drops the scheme prefix
// and trailing slash so a placeholder like {domain} resolves to a bare host
// whether the user typed `acme.example.com`, `https://acme.example.com`, or
// `https://acme.example.com/`. Applied only to placeholders carrying a
// spec-declared default (server-URL variables); path-positional placeholders
// like {tenant} pass through unchanged because their accepted shapes are
// API-specific.
func normalizeEndpointTemplateValue(v string) string {
	// Strip scheme prefix case-insensitively: users paste `HTTPS://` from
	// some browsers' address bars, and Go's TrimPrefix is exact-match.
	// Callers TrimSpace the env-var value before passing it in.
	if len(v) >= 8 && strings.EqualFold(v[:8], "https://") {
		v = v[8:]
	} else if len(v) >= 7 && strings.EqualFold(v[:7], "http://") {
		v = v[7:]
	}
	return strings.TrimRight(v, "/")
}

func (c *Config) AuthHeader() string {
	if c.AuthHeaderVal != "" {
		return c.AuthHeaderVal
	}
	token := c.ProxmoxApiToken
	if token == "" {
		return ""
	}
	if c.ProxmoxApiToken == "" {
		return ""
	}
	replacements := map[string]string{
		"token":             token,
		"api_token":         c.ProxmoxApiToken,
		"PROXMOX_API_TOKEN": c.ProxmoxApiToken,
	}
	return applyAuthFormat("PVEAPIToken={token}", replacements)
}

